// One pinned CPU model, host RAM, and the CPU's own instruction/data bus.
//
// This host is intentionally not a second harness system: the model is the CPU
// wrapper already generated by the local-harness builder (structural.sv), and the
// only host-side services are RAM, boot/reset, one bus transactor and a tiny case
// loop.  No target IP, DMA or MMIO window exists.
//
// Three memory-bus shapes are served, one per build, selected by the macros the
// runner emits from the pinned artifact's own role map:
//
//   CPU_BUS_OBI        Ibex/CV32E40P: separate instruction and data OBI channels
//                      (req/gnt/addr/rvalid/rdata, plus byte enables on data).
//   CPU_BUS_WISHBONE   PicoRV32 classic Wishbone master: one unified port
//                      (cyc/stb/we/adr/sel/dat_w/dat_r/ack), one transaction at a
//                      time, acknowledged one tick after the request.
//   CPU_BUS_AXI4LITE   PicoRV32 AXI4-Lite master: one unified port with AR/R and
//                      AW/W/B handshakes and write strobes.
//
// A unified port is not split into "instruction" and "data" here: the RAM is
// addressed identically either way, and no retirement claim is derived from it.
// Which buses a CPU exports is a property of the generated wrapper, so an absent
// shape is refused by the Python runner before a model is built.
//
// Two input shapes exist:
//
//   --records     the historical data-only batch: one mailbox word per case, a
//                 fixed polling program, the result word compared with input+1.
//   --programs    a generated-program batch: every case is a different RV32
//                 program installed in its own slot, chained by the trailer
//                 jumps, and the case compares the real retirement trace (when
//                 RVFI is exported) and the real data window with the Python
//                 reference model's expectation.
//
// Assertions: the model is built with --assert.  The upstream CPU's prim_assert
// macros choose dummy bodies when VERILATOR is predefined, so the assertion build
// additionally undefines that tool macro (see assertion_build_flags).  At run time
// VerilatedContext::fatalOnError(false) keeps a failing assertion from calling
// exit(); the assertion still prints %Error and sets gotError()/gotFinish(), which
// this host turns into an `assertion` event and exit code 3.  The Python runner
// keeps the child process's stdout/stderr, so the text/file/line survive even if a
// future model aborts before the event line.
#include "cpu_only_config.h"
#include "Vlocal_cpu.h"
#include "verilated.h"
#include "inprocess_memory.h"

#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

using myfuzz::inprocess_spike::Memory;

namespace {

struct Pending {
  bool valid = false;
  uint32_t address = 0;
  bool write = false;
  uint32_t wdata = 0;
  unsigned be = 0;
};

std::string hex32(uint32_t value) {
  std::ostringstream text;
  text << "0x" << std::hex << value;
  return text.str();
}

uint32_t parse_word(const std::string &text) {
  std::size_t used = 0;
  unsigned long value = std::stoul(text, &used, 0);
  if (used != text.size() || value > 0xfffffffful)
    throw std::runtime_error("invalid-record-word:" + text);
  return static_cast<uint32_t>(value);
}

std::vector<uint32_t> parse_records(const std::string &text) {
  std::vector<uint32_t> words;
  std::size_t start = 0;
  while (start <= text.size()) {
    const std::size_t comma = text.find(',', start);
    const std::string item = text.substr(start, comma == std::string::npos
                                                    ? std::string::npos
                                                    : comma - start);
    if (!item.empty()) words.push_back(parse_word(item));
    if (comma == std::string::npos) break;
    start = comma + 1;
  }
  return words;
}

// FNV-1a 32 over 32-bit little-endian fields.  The same pair
// (2166136261u/16777619u) the shared in-process host uses in namespace
// ``f1_trace`` and ``myfuzz.fuzz.f1_program_gate.trace_hash`` computes from a
// reference trace, so the two hashes are comparable values, not two conventions.
namespace fnv32 {

inline uint32_t step(uint32_t hash, uint32_t value) {
  for (unsigned byte = 0; byte < 4; ++byte) {
    hash ^= (value >> (8 * byte)) & 0xffu;
    hash *= 16777619u;
  }
  return hash;
}

inline uint32_t entry(uint32_t hash, uint32_t pc, uint32_t insn, uint32_t rd,
                      uint32_t wdata) {
  return step(step(step(step(hash, pc), insn), rd), wdata);
}

inline uint32_t offset_basis() { return 2166136261u; }

}  // namespace fnv32

// FNV-1a 32 of the words the CPU can actually fetch from [base, base+4*words).
// It is read out of the RAM image the model is served from, so it hashes the
// installed bytes, never a value handed in on the command line.
uint32_t window_hash(const Memory &memory, uint32_t base, unsigned words) {
  uint32_t hash = fnv32::offset_basis();
  for (unsigned index = 0; index < words; ++index)
    hash = fnv32::step(hash, memory.read(base + 4 * index));
  return hash;
}

// One case of a generated-program batch.  The host is told only where the case's
// instruction words are, which data window it owns, and which word its trailer
// stores: everything compared below is then read out of the model's own RVFI
// channel or out of the RAM the model wrote.
struct ProgramCase {
  unsigned index = 0;
  uint32_t start = 0;   // first program word address
  uint32_t end = 0;     // one past the last program word (exclusive)
  uint32_t data = 0;    // data window base (x18 for this case)
  unsigned data_words = 0;
  uint32_t done = 0;    // word the trailer stores
  uint32_t done_value = 0;
  uint32_t trailer = 0;  // address of the trailer's store word
};

// ``#`` comments and blank lines are allowed; every other line is
// ``prog <index> start=<hex> end=<hex> data=<hex> data_words=<dec>
//  done=<hex> done_value=<hex> trailer=<hex>``.
std::vector<ProgramCase> parse_programs(const std::string &path) {
  std::ifstream input(path);
  if (!input) throw std::runtime_error("programs-file-not-found:" + path);
  std::vector<ProgramCase> cases;
  std::string line;
  while (std::getline(input, line)) {
    const std::size_t comment = line.find('#');
    if (comment != std::string::npos) line.erase(comment);
    std::istringstream stream(line);
    std::string kind;
    if (!(stream >> kind)) continue;
    if (kind != "prog") throw std::runtime_error("programs-line-invalid:" + line);
    ProgramCase row;
    if (!(stream >> row.index)) throw std::runtime_error("programs-line-invalid:" + line);
    std::string token;
    unsigned seen = 0;
    while (stream >> token) {
      const std::size_t split = token.find('=');
      if (split == std::string::npos)
        throw std::runtime_error("programs-line-invalid:" + line);
      const std::string key = token.substr(0, split);
      const std::string raw = token.substr(split + 1);
      std::size_t used = 0;
      const unsigned long value = std::stoul(raw, &used, 0);
      if (used != raw.size() || value > 0xfffffffful)
        throw std::runtime_error("programs-line-invalid:" + line);
      if (key == "start") row.start = static_cast<uint32_t>(value);
      else if (key == "end") row.end = static_cast<uint32_t>(value);
      else if (key == "data") row.data = static_cast<uint32_t>(value);
      else if (key == "data_words") row.data_words = static_cast<unsigned>(value);
      else if (key == "done") row.done = static_cast<uint32_t>(value);
      else if (key == "done_value") row.done_value = static_cast<uint32_t>(value);
      else if (key == "trailer") row.trailer = static_cast<uint32_t>(value);
      else throw std::runtime_error("programs-line-invalid:" + line);
      ++seen;
    }
    if (seen != 7 || row.end <= row.start || (row.end - row.start) % 4
        || row.end - row.start > 64 || row.data_words == 0
        || row.data_words > 64)
      throw std::runtime_error("programs-line-invalid:" + line);
    cases.push_back(row);
  }
  if (cases.empty()) throw std::runtime_error("programs-required");
  return cases;
}

class Bench {
 public:
  Bench(Memory &ram, bool assertions) : ram_(ram), assertions_(assertions) {
    context_.fatalOnError(false);
    context_.assertOn(assertions_);
    model_ = new CPU_MODEL(&context_, "cpu");
    model_->clk = 0;
    model_->reset = 1;
    clear_inputs();
  }

  ~Bench() {
    model_->final();
    delete model_;
  }

  void clear_inputs() {
#ifdef CPU_I_GNT
    model_->CPU_I_GNT = 0;
#endif
#ifdef CPU_I_RVALID
    model_->CPU_I_RVALID = 0;
#endif
#ifdef CPU_I_RDATA
    model_->CPU_I_RDATA = 0;
#endif
#ifdef CPU_I_ERROR
    model_->CPU_I_ERROR = 0;
#endif
#ifdef CPU_D_GNT
    model_->CPU_D_GNT = 0;
#endif
#ifdef CPU_D_RVALID
    model_->CPU_D_RVALID = 0;
#endif
#ifdef CPU_D_RDATA
    model_->CPU_D_RDATA = 0;
#endif
#ifdef CPU_D_ERROR
    model_->CPU_D_ERROR = 0;
#endif
#ifdef CPU_IRQ
    model_->CPU_IRQ = 0;
#endif
#ifdef CPU_MEM_ACK
    model_->CPU_MEM_ACK = 0;
#endif
#ifdef CPU_MEM_DAT_R
    model_->CPU_MEM_DAT_R = 0;
#endif
#ifdef CPU_AR_READY
    model_->CPU_AR_READY = 0;
#endif
#ifdef CPU_AW_READY
    model_->CPU_AW_READY = 0;
#endif
#ifdef CPU_W_READY
    model_->CPU_W_READY = 0;
#endif
#ifdef CPU_R_VALID
    model_->CPU_R_VALID = 0;
#endif
#ifdef CPU_R_DATA
    model_->CPU_R_DATA = 0;
#endif
#ifdef CPU_B_VALID
    model_->CPU_B_VALID = 0;
#endif
  }

  // One complete host tick: low phase settles inputs, rising edge samples them,
  // high phase observes outputs.  A response is delivered one tick after the
  // matching request on every shape, with a single outstanding transaction.
  bool tick(bool fault_pulse) {
    model_->clk = 0;
    model_->eval();
    const bool reset = tick_ < CPU_RESET_ASSERT;
    model_->reset = reset ? 1 : 0;
    drive_bus(reset, fault_pulse);
    model_->clk = 1;
    model_->eval();
    ++tick_;
    settle_bus();
    sample_retirement();
    return context_.gotError() || context_.gotFinish();
  }

  // Pre-edge: sample the model's request pins and drive this tick's response.
  void drive_bus(bool reset, bool fault_pulse) {
#if defined(CPU_BUS_OBI)
#ifdef CPU_I_REQ
    const bool ireq = model_->CPU_I_REQ != 0;
    const bool igrant = !reset && ireq && !ipending_ && !ideliver_;
#else
    const bool igrant = false;
#endif
#ifdef CPU_D_REQ
    const bool dreq = model_->CPU_D_REQ != 0;
    const bool dgrant = !reset && dreq && !dpending_ && !ddeliver_;
#else
    const bool dgrant = false;
#endif

#ifdef CPU_I_GNT
    model_->CPU_I_GNT = igrant ? 1 : 0;
#endif
#ifdef CPU_D_GNT
    model_->CPU_D_GNT = dgrant ? 1 : 0;
#endif
    if (igrant) {
      ipending_ = true;
      iaddress_ = model_->CPU_I_ADDR;
      ++bus_reads_;
    }
    if (dgrant) {
      dpending_ = true;
      daddress_ = model_->CPU_D_ADDR;
      dwrite_ = model_->CPU_D_WE != 0;
      dwdata_ = model_->CPU_D_WDATA;
      dbe_ = model_->CPU_D_BE;
      if (dwrite_) {
        ram_.write(daddress_, dwdata_, dbe_);
        ++bus_writes_;
      } else {
        ++bus_reads_;
      }
    }

#ifdef CPU_I_RVALID
    model_->CPU_I_RVALID = ideliver_ ? 1 : 0;
#endif
#ifdef CPU_I_RDATA
    model_->CPU_I_RDATA = irdata_;
#endif
#ifdef CPU_D_RVALID
    model_->CPU_D_RVALID = (ddeliver_ || fault_pulse) ? 1 : 0;
#endif
#ifdef CPU_D_RDATA
    model_->CPU_D_RDATA = drdata_;
#endif
#ifdef CPU_D_ERROR
    model_->CPU_D_ERROR = 0;
#endif
#ifdef CPU_I_ERROR
    model_->CPU_I_ERROR = 0;
#endif
#elif defined(CPU_BUS_WISHBONE)
    // Classic Wishbone: cyc & stb is the request, ack is the response.  The
    // master must deassert cyc/stb before another transaction is accepted, so a
    // held request can never be serviced twice (a duplicated store would be a
    // fabricated write).
    (void)fault_pulse;
    const bool active = !reset && model_->CPU_MEM_CYC != 0 && model_->CPU_MEM_STB != 0;
    bool ack = false;
    if (!active) {
      wb_armed_ = true;
      wb_pending_ = false;
    } else if (wb_armed_ && !wb_pending_) {
      const uint32_t address = model_->CPU_MEM_ADR;
      const bool write = model_->CPU_MEM_WE != 0;
      const unsigned be = model_->CPU_MEM_SEL;
      wb_armed_ = false;
      wb_pending_ = true;
      if (write) {
        ram_.write(address, model_->CPU_MEM_DAT_W, be);
        ++bus_writes_;
      } else {
        wb_rdata_ = ram_.read(address);
        ++bus_reads_;
      }
    } else if (wb_pending_) {
      ack = true;
      wb_pending_ = false;
    }
    model_->CPU_MEM_ACK = ack ? 1 : 0;
    model_->CPU_MEM_DAT_R = wb_rdata_;
#elif defined(CPU_BUS_AXI4LITE)
    // AXI4-Lite: AR/R for reads and AW+W/B for writes.  One read and one write
    // may be in flight; each response is raised one tick after its request and
    // held until the master's READY handshake.
    (void)fault_pulse;
    const bool b_busy = axi_b_valid_ || axi_aw_pending_ || axi_w_pending_;
    const bool ar_ready = !reset && !axi_ar_pending_ && !axi_r_valid_;
    const bool aw_ready = !reset && !b_busy;
    const bool w_ready = !reset && !b_busy;
    axi_r_seen_ready_ = model_->CPU_R_READY != 0;
    axi_b_seen_ready_ = model_->CPU_B_READY != 0;
    if (axi_ar_pending_) {
      // The accepted address is answered on the following tick.
      axi_r_data_ = ram_.read(axi_ar_addr_);
      axi_r_valid_ = true;
      axi_ar_pending_ = false;
      ++bus_reads_;
    }
    if (ar_ready && model_->CPU_AR_VALID != 0) {
      axi_ar_addr_ = model_->CPU_AR_ADDR;
      axi_ar_pending_ = true;
    }
    if (aw_ready && model_->CPU_AW_VALID != 0) {
      axi_aw_addr_ = model_->CPU_AW_ADDR;
      axi_aw_pending_ = true;
    }
    if (w_ready && model_->CPU_W_VALID != 0) {
      axi_w_data_ = model_->CPU_W_DATA;
      axi_w_strb_ = model_->CPU_W_STRB;
      axi_w_pending_ = true;
    }
    if (axi_aw_pending_ && axi_w_pending_ && !axi_b_valid_) {
      ram_.write(axi_aw_addr_, axi_w_data_, axi_w_strb_);
      axi_aw_pending_ = false;
      axi_w_pending_ = false;
      axi_b_valid_ = true;
      ++bus_writes_;
    }
    model_->CPU_AR_READY = ar_ready ? 1 : 0;
    model_->CPU_AW_READY = aw_ready ? 1 : 0;
    model_->CPU_W_READY = w_ready ? 1 : 0;
    model_->CPU_R_VALID = axi_r_valid_ ? 1 : 0;
    model_->CPU_R_DATA = axi_r_data_;
    model_->CPU_B_VALID = axi_b_valid_ ? 1 : 0;
#else
#error "one CPU_BUS_* macro must be defined by the generated cpu_only_config.h"
#endif
  }

  // Post-edge: per-shape bookkeeping for the handshake that just completed.
  void settle_bus() {
#if defined(CPU_BUS_OBI)
    if (ideliver_) {
      ideliver_ = false;
      ipending_ = false;
    }
    if (ddeliver_) {
      ddeliver_ = false;
      dpending_ = false;
    }
    if (ipending_ && !ideliver_) {
      irdata_ = ram_.read(iaddress_);
      ideliver_ = true;
    }
    if (dpending_ && !ddeliver_) {
      drdata_ = ram_.read(daddress_);
      ddeliver_ = true;
    }
#elif defined(CPU_BUS_WISHBONE)
    // The ack cycle and the request latch are both resolved in drive_bus.
#elif defined(CPU_BUS_AXI4LITE)
    if (axi_r_valid_ && axi_r_seen_ready_) axi_r_valid_ = false;
    if (axi_b_valid_ && axi_b_seen_ready_) axi_b_valid_ = false;
#endif
  }

  void sample_retirement() {
    retired_this_tick_ = false;
#ifdef CPU_RVFI_VALID
    if (model_->CPU_RVFI_VALID) {
      ++retires_;
      last_pc_ = model_->CPU_RVFI_PC_RDATA;
      last_insn_ = model_->CPU_RVFI_INSN;
      ++rvfi_order_;
      retired_this_tick_ = true;
#ifdef CPU_RVFI_RD_ADDR
      last_rd_ = model_->CPU_RVFI_RD_ADDR;
#endif
#ifdef CPU_RVFI_RD_WDATA
      last_wdata_ = model_->CPU_RVFI_RD_WDATA;
#endif
    }
#endif
  }

  bool retired_this_tick() const { return retired_this_tick_; }
  uint32_t last_rd() const { return last_rd_; }
  uint32_t last_wdata() const { return last_wdata_; }
  uint64_t bus_reads() const { return bus_reads_; }
  uint64_t bus_writes() const { return bus_writes_; }

  uint64_t tick() const { return tick_; }
  unsigned retires() const { return retires_; }
  bool retirement_observed() const {
#ifdef CPU_RVFI_VALID
    return true;
#else
    return false;
#endif
  }
  uint32_t last_pc() const { return last_pc_; }
  uint32_t last_insn() const { return last_insn_; }
  bool assertions() const { return assertions_; }
  bool got_error() const { return context_.gotError(); }
  bool got_finish() const { return context_.gotFinish(); }

 private:
  VerilatedContext context_;
  CPU_MODEL *model_ = nullptr;
  Memory &ram_;
  bool assertions_;
  uint64_t tick_ = 0;
  bool ipending_ = false, ideliver_ = false;
  bool dpending_ = false, ddeliver_ = false;
  uint32_t iaddress_ = 0, daddress_ = 0;
  uint32_t irdata_ = 0, drdata_ = 0;
  uint32_t dwdata_ = 0;
  bool dwrite_ = false;
  unsigned dbe_ = 0;
  unsigned retires_ = 0;
  uint64_t rvfi_order_ = 0;
  uint32_t last_pc_ = 0, last_insn_ = 0;
  uint32_t last_rd_ = 0, last_wdata_ = 0;
  bool retired_this_tick_ = false;
  // Wishbone service state.
  bool wb_armed_ = true, wb_pending_ = false;
  uint32_t wb_rdata_ = 0;
  // AXI4-Lite service state.
  bool axi_ar_pending_ = false, axi_r_valid_ = false, axi_r_seen_ready_ = false;
  bool axi_aw_pending_ = false, axi_w_pending_ = false;
  bool axi_b_valid_ = false, axi_b_seen_ready_ = false;
  uint32_t axi_ar_addr_ = 0, axi_aw_addr_ = 0;
  uint32_t axi_r_data_ = 0, axi_w_data_ = 0;
  unsigned axi_w_strb_ = 0;
  // Bus traffic the host really served (a total, never a retirement claim).
  uint64_t bus_reads_ = 0, bus_writes_ = 0;
};

}  // namespace

int main(int argc, char **argv) {
  std::string firmware, records_text, fault_kind, programs_path;
  uint32_t max_ticks = CPU_DEFAULT_MAX_TICKS;
  uint32_t fault_tick = 0;
  bool assertions = false, quiet = false;
  try {
    for (int index = 1; index < argc; ++index) {
      const std::string argument = argv[index];
      auto value = [&](const char *name) -> std::string {
        if (index + 1 >= argc) throw std::runtime_error(std::string("missing-value:") + name);
        return argv[++index];
      };
      if (argument == "--firmware") firmware = value("--firmware");
      else if (argument == "--records") records_text = value("--records");
      else if (argument == "--programs") programs_path = value("--programs");
      else if (argument == "--max-ticks") max_ticks = static_cast<uint32_t>(std::stoul(value("--max-ticks")));
      else if (argument == "--assertions") {
        const std::string flag = value("--assertions");
        if (flag == "on") assertions = true;
        else if (flag == "off") assertions = false;
        else throw std::runtime_error("invalid-assertions-flag");
      } else if (argument == "--fault") fault_kind = value("--fault");
      else if (argument == "--fault-tick") fault_tick = static_cast<uint32_t>(std::stoul(value("--fault-tick")));
      else if (argument == "--quiet") quiet = true;
      else throw std::runtime_error("unknown-argument:" + argument);
    }
    if (firmware.empty()) throw std::runtime_error("firmware-required");
    if (!fault_kind.empty() && fault_kind != "spurious-data-rvalid")
      throw std::runtime_error("unsupported-fault-kind");
    if (!fault_kind.empty() && fault_tick == 0)
      throw std::runtime_error("fault-tick-required");
    if (!programs_path.empty() && !records_text.empty())
      throw std::runtime_error("records-and-programs-are-alternatives");

    Memory ram(CPU_RAM_BASE, CPU_RAM_SIZE);
    ram.load(firmware.c_str());
    Bench bench(ram, assertions);

    // Reset and the declared release window are part of the model's boot; no
    // case input is installed before the CPU has been released for its full
    // declared release interval.
    for (unsigned index = 0; index < CPU_RESET_ASSERT; ++index) {
      if (bench.tick(false)) {
        std::cout << "assertion tick=" << bench.tick() << " case=0 model=cpu"
                  << " got_error=1 got_finish=" << (bench.got_finish() ? 1 : 0) << "\n";
        return 3;
      }
    }
    for (unsigned index = 0; index < CPU_RESET_RELEASE; ++index) {
      if (bench.tick(false)) {
        std::cout << "assertion tick=" << bench.tick() << " case=0 model=cpu"
                  << " got_error=1 got_finish=" << (bench.got_finish() ? 1 : 0) << "\n";
        return 3;
      }
    }

    if (!fault_kind.empty()) {
#if !defined(CPU_BUS_OBI)
      // The declared fault is a spurious response on the OBI data channel.  A
      // unified Wishbone/AXI port has no such channel, and inventing an
      // equivalent would be a different fault, so this host refuses by name.
      std::cout << "environment_error reason=fault-needs-obi-data-channel\n";
      return 4;
#else
      // The declared fault case runs an instruction-only program.  At the named
      // tick the host drives a response on the data bus even though the CPU has
      // no data access outstanding; Ibex's own developer assertions are the
      // observable that fails.
      // ``--fault-tick`` is an absolute host tick (reset and release included),
      // so the reported assertion tick and the declared input use one clock.
      const uint32_t deadline = fault_tick + 32;
      while (bench.tick() < deadline && bench.tick() < max_ticks) {
        const bool pulse = (bench.tick() + 1 == fault_tick);
        const bool failed = bench.tick(pulse);
        if (failed) {
          std::cout << "assertion tick=" << bench.tick() << " case=0 model=cpu"
                    << " got_error=" << (bench.got_error() ? 1 : 0)
                    << " got_finish=" << (bench.got_finish() ? 1 : 0)
                    << " fault=" << fault_kind << "\n";
          std::cout << "summary assertion_failed cases=1 failed=1 ticks="
                    << bench.tick() << " retires=" << bench.retires()
                    << " assertions=on\n";
          return 3;
        }
      }
      std::cout << "environment_error reason=assertion_not_triggered case=0 tick="
                << bench.tick() << "\n";
      return 4;
#endif
    }

    if (!programs_path.empty()) {
      // A generated-program batch.  Each case is a different RV32 program in its
      // own slot; the trailers chain the cases, so one boot serves the batch.
      // Everything compared here is read back from the model: the retirement
      // trace from RVFI (when the CPU exports it), the data window and the case's
      // completion word from the RAM the model wrote.
      const std::vector<ProgramCase> programs = parse_programs(programs_path);
      unsigned failed_cases = 0;
      for (const ProgramCase &program : programs) {
        const unsigned words = static_cast<unsigned>((program.end - program.start) / 4);
        std::vector<uint32_t> before(program.data_words);
        for (unsigned index = 0; index < program.data_words; ++index)
          before[index] = ram.read(program.data + 4 * index);
        const uint32_t window_before = window_hash(ram, program.data, program.data_words);
        const uint32_t program_hash = window_hash(ram, program.start, words);
        const uint64_t reads_before = bench.bus_reads();
        const uint64_t writes_before = bench.bus_writes();
        const auto case_started = std::chrono::steady_clock::now();
        const uint64_t started = bench.tick();
        uint32_t trace_hash = fnv32::offset_basis();
        unsigned trace_count = 0, writebacks = 0;
        uint32_t rd_mask = 0, previous_pc = 0;
        bool have_previous = false, pc_ordered = true, insns_match = true;
        uint32_t last_pc = 0, last_insn = 0, last_rd = 0, last_wdata = 0;
        bool done = false, failed = false;
        while (true) {
          if (bench.tick(false)) {
            failed = true;
            break;
          }
          if (bench.retired_this_tick()) {
            const uint32_t pc = bench.last_pc();
            if (pc >= program.start && pc < program.end) {
              const uint32_t insn = bench.last_insn();
              const uint32_t rd = bench.last_rd();
              const uint32_t wdata = bench.last_wdata();
              if (have_previous && pc <= previous_pc) pc_ordered = false;
              previous_pc = pc;
              have_previous = true;
              // The retired word must be the word installed at that PC; a CPU
              // that retires something else is a finding, never a pass.
              if (ram.read(pc) != insn) insns_match = false;
              trace_hash = fnv32::entry(trace_hash, pc, insn, rd, wdata);
              ++trace_count;
              if (rd) {
                rd_mask |= uint32_t(1) << rd;
                ++writebacks;
              }
              last_pc = pc;
              last_insn = insn;
              last_rd = rd;
              last_wdata = wdata;
            }
          }
          if (ram.read(program.done) == program.done_value) {
            done = true;
            break;
          }
          if (bench.tick() - started > max_ticks) break;
        }
        if (failed) {
          std::cout << "assertion tick=" << bench.tick() << " case=" << program.index
                    << " input=program model=cpu"
                    << " got_error=" << (bench.got_error() ? 1 : 0)
                    << " got_finish=" << (bench.got_finish() ? 1 : 0) << "\n";
          return 3;
        }
        if (!done) {
          std::cout << "environment_error reason=case_timeout case=" << program.index
                    << " tick=" << bench.tick() << " input=program\n";
          std::cout << "summary environment_failed cases=" << programs.size()
                    << " failed=" << (failed_cases + 1) << " ticks=" << bench.tick()
                    << " retires=" << (bench.retirement_observed() ? "known" : "unknown")
                    << " assertions=" << (assertions ? "on" : "off")
                    << " programs=" << programs.size() << "\n";
          return 4;
        }
        unsigned changed = 0;
        for (unsigned index = 0; index < program.data_words; ++index)
          if (ram.read(program.data + 4 * index) != before[index]) ++changed;
        std::cout << "case " << program.index << " observations_passed"
                  << " program_hash=" << hex32(program_hash)
                  << " program_words=" << words << " retires=";
        if (bench.retirement_observed())
          std::cout << trace_count << " pc=" << hex32(last_pc)
                    << " insn=" << hex32(last_insn);
        else
          std::cout << "unknown pc=unknown insn=unknown";
        std::cout << " trace=";
        if (bench.retirement_observed()) std::cout << hex32(trace_hash);
        else std::cout << "unknown";
        std::cout << " trace_count=";
        if (bench.retirement_observed()) std::cout << trace_count;
        else std::cout << "unknown";
        std::cout << " writebacks=";
        if (bench.retirement_observed()) std::cout << writebacks;
        else std::cout << "unknown";
        std::cout << " rd_mask=";
        if (bench.retirement_observed()) std::cout << hex32(rd_mask);
        else std::cout << "unknown";
        std::cout << " pc_order=";
        if (bench.retirement_observed()) std::cout << (pc_ordered ? 1 : 0);
        else std::cout << "unknown";
        std::cout << " insns_match=";
        if (bench.retirement_observed()) std::cout << (insns_match ? 1 : 0);
        else std::cout << "unknown";
        std::cout << " last_rd=" << last_rd
                  << " last_wdata=" << hex32(last_wdata)
                  << " done=" << hex32(ram.read(program.done))
                  << " done_value=" << hex32(program.done_value)
                  << " data_hash_before=" << hex32(window_before)
                  << " data_hash_after="
                  << hex32(window_hash(ram, program.data, program.data_words))
                  << " data_words=" << program.data_words
                  << " data_changed=" << changed
                  << " bus_reads=" << (bench.bus_reads() - reads_before)
                  << " bus_writes=" << (bench.bus_writes() - writes_before)
                  << " ticks=" << (bench.tick() - started)
                  << " wall_us="
                  << std::chrono::duration_cast<std::chrono::microseconds>(
                         std::chrono::steady_clock::now() - case_started).count()
                  << "\n";
      }
      std::cout << "summary observations_passed cases=" << programs.size()
                << " failed=0 ticks=" << bench.tick() << " retires=";
      if (bench.retirement_observed()) std::cout << "known";
      else std::cout << "unknown";
      std::cout << " assertions=" << (assertions ? "on" : "off")
                << " model=cpu programs=" << programs.size()
                << " bus=" << CPU_BUS_NAME << "\n";
      return 0;
    }

    const std::vector<uint32_t> records = parse_records(records_text);
    if (records.empty()) throw std::runtime_error("records-required");
    unsigned failed_cases = 0;
    for (std::size_t index = 0; index < records.size(); ++index) {
      const uint32_t input = records[index];
      const uint32_t expected = input + 1u;
      ram.write(CPU_MAILBOX_ADDRESS, input, 0xf);
      // Preload a sentinel that is provably different from the expected result,
      // including the 0xffffffff -> 0x00000000 wrap case.  The case therefore
      // cannot pass on the host's clear write alone.
      ram.write(CPU_RESULT_ADDRESS, expected ^ 1u, 0xf);
      const auto case_started = std::chrono::steady_clock::now();
      const uint64_t started = bench.tick();
      const unsigned retires_before = bench.retires();
      bool observed = false;
      while (bench.tick(false)) {
        std::cout << "assertion tick=" << bench.tick() << " case=" << index
                  << " input=" << hex32(input) << " model=cpu"
                  << " got_error=1 got_finish=" << (bench.got_finish() ? 1 : 0) << "\n";
        return 3;
      }
      while (bench.tick() - started <= max_ticks) {
        if (ram.read(CPU_RESULT_ADDRESS) == expected) {
          observed = true;
          break;
        }
        if (bench.tick(false)) {
          std::cout << "assertion tick=" << bench.tick() << " case=" << index
                    << " input=" << hex32(input) << " model=cpu"
                    << " got_error=1 got_finish=" << (bench.got_finish() ? 1 : 0) << "\n";
          return 3;
        }
      }
      if (!observed) {
        std::cout << "environment_error reason=case_timeout case=" << index
                  << " tick=" << bench.tick() << " input=" << hex32(input) << "\n";
        std::cout << "summary environment_failed cases=" << records.size()
                  << " failed=" << (failed_cases + 1) << " ticks=" << bench.tick()
                  << " retires=";
        if (bench.retirement_observed()) std::cout << bench.retires();
        else std::cout << "unknown";
        std::cout << " assertions=" << (assertions ? "on" : "off") << "\n";
        return 4;
      }
      std::cout << "case " << index << " observations_passed input=" << hex32(input)
                << " expected=" << hex32(expected)
                << " result=" << hex32(ram.read(CPU_RESULT_ADDRESS))
                << " ticks=" << (bench.tick() - started)
                << " retires=";
      if (bench.retirement_observed())
        std::cout << (bench.retires() - retires_before)
                  << " pc=" << hex32(bench.last_pc())
                  << " insn=" << hex32(bench.last_insn());
      else
        std::cout << "unknown pc=unknown insn=unknown";
      std::cout << " wall_us=" << std::chrono::duration_cast<std::chrono::microseconds>(
                     std::chrono::steady_clock::now() - case_started).count() << "\n";
    }
    std::cout << "summary observations_passed cases=" << records.size()
              << " failed=0 ticks=" << bench.tick() << " retires=";
    if (bench.retirement_observed()) std::cout << bench.retires();
    else std::cout << "unknown";
    std::cout << " assertions=" << (assertions ? "on" : "off")
              << " model=cpu\n";
    return 0;
  } catch (const std::exception &error) {
    std::cout << "environment_error reason=host_exception message=" << error.what() << "\n";
    return 4;
  }
}
